INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(43611, 'Proverbs 16:9', 'Proverbs', 16, 9, 'انسان په زړه کې ځان ته د تګ لارې جوړوي خو څښتن د هغه د قدمونو لارښوونه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_9.mp3', '', 1761754199, 1761754199),
(43612, 'Proverbs 16:10', 'Proverbs', 16, 10, 'د پاچا خبرې د الهام په څېر دي او په قضاوت کې هېڅ بې‌انصافي نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_10.mp3', '', 1761754199, 1761754199),
(43613, 'Proverbs 16:11', 'Proverbs', 16, 11, 'سمه تله او تول د څښتن د قضاوت نښه ده او د وزن کولو دپاره یې ټول کاڼي جوړ کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_11.mp3', '', 1761754199, 1761754199),
(43614, 'Proverbs 16:12', 'Proverbs', 16, 12, 'پاچاهان د بدو کارونو نه کرکه کوي ځکه د پاچاهۍ تخت یې د عدالت په بنیاد ولاړ دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_12.mp3', '', 1761754199, 1761754199),
(43615, 'Proverbs 16:13', 'Proverbs', 16, 13, 'پاچاهان په رښتینو خبرو خوشحالیږي او له هغه چا سره مینه کوي چې رښتیا وایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_13.mp3', '', 1761754199, 1761754199),
(43616, 'Proverbs 16:14', 'Proverbs', 16, 14, 'د پاچا غوسه د مرګ پیغام دی خو د حکمت خاوند د هغه قهر سړوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_14.mp3', '', 1761754199, 1761754199),
(43617, 'Proverbs 16:15', 'Proverbs', 16, 15, 'د پاچا په ورین تندي کې د ژوندون زېری وي او رحم یې د پسرلي د ورېځې په څېر باران وروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_15.mp3', '', 1761754199, 1761754199),
(43618, 'Proverbs 16:16', 'Proverbs', 16, 16, 'د حکمت حاصلول له سرو زرو نه څو چنده بهتر دي او عقل لاسته راوړل له سپینو زرو نه غوره دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_16.mp3', '', 1761754199, 1761754199),
(43619, 'Proverbs 16:17', 'Proverbs', 16, 17, 'د صادقانو سمه لار انسان د بدۍ او بلا نه ساتي څوک چې خپلې لارې ته پام کوي نو خپل ځان ساتي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_17.mp3', '', 1761754199, 1761754199),
(43620, 'Proverbs 16:18', 'Proverbs', 16, 18, 'مغرور تباه کیږي کبرجن راغورځیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_18.mp3', '', 1761754199, 1761754199),
(43621, 'Proverbs 16:19', 'Proverbs', 16, 19, 'ښه ده چې انسان عاجز وي او د غریبانو سره اړیکې ولري له دې نه چې د مغرورانو سره په غنیمت کې شریک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_19.mp3', '', 1761754199, 1761754199),
(43622, 'Proverbs 16:20', 'Proverbs', 16, 20, 'بریالی دی هغه څوک چې کلام اوري او بختور دی هغه چې په څښتن باور کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_20.mp3', '', 1761754199, 1761754199),
(43623, 'Proverbs 16:21', 'Proverbs', 16, 21, 'د حکمت خاوند له خپل عقل څخه پېژندل کیږي او خوږه ژبه په زده کړه کې ډېره قناعت بخښونکې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_21.mp3', '', 1761754199, 1761754199),
(43624, 'Proverbs 16:22', 'Proverbs', 16, 22, 'څوک چې هوښیاري لري هغه یې د ژوند سرچینه ده خو جهالت د جاهلانو دپاره د سزا لښته ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_22.mp3', '', 1761754199, 1761754199),
(43625, 'Proverbs 16:23', 'Proverbs', 16, 23, 'د حکمت د خاوند زړه د هغه ژبه هوښیاروي چې هرې خبرې ته یې په قناعت ورکولو کې ګټه رسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_23.mp3', '', 1761754199, 1761754199),
(43626, 'Proverbs 16:24', 'Proverbs', 16, 24, 'مهربانې خبرې د شاتو د مچیو د ډک چک په شان دي چې د روح دپاره خواږه او د بدن دپاره شفا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_24.mp3', '', 1761754199, 1761754199),
(43627, 'Proverbs 16:25', 'Proverbs', 16, 25, 'د یو انسان په نظر یوه لار سمه ښکاري خو په اخر کې هغه په مرګ پای ته رسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_25.mp3', '', 1761754199, 1761754199),
(43628, 'Proverbs 16:26', 'Proverbs', 16, 26, 'د یو مزدور لوږه هغه سخت کار ته مجبوروي او وږې ګېډه سړی نور ډېر کار ته هڅوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_26.mp3', '', 1761754199, 1761754199),
(43629, 'Proverbs 16:27', 'Proverbs', 16, 27, 'بېکاره انسان بدې نقشې جوړوي او خبرې یې د اور په شان سوځول کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_27.mp3', '', 1761754199, 1761754199),
(43630, 'Proverbs 16:28', 'Proverbs', 16, 28, 'بې‌لارې سړی شخړو ته لمن وهي او غیبت کوونکی نژدې دوستان جدا کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_28.mp3', '', 1761754199, 1761754199),
(43631, 'Proverbs 16:29', 'Proverbs', 16, 29, 'ظالم خپل ملګری بې‌لارې کوي او بدې لارې ته یې هڅوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_29.mp3', '', 1761754199, 1761754199),
(43632, 'Proverbs 16:30', 'Proverbs', 16, 30, 'څوک چې سترګې او وروځې وهي بدې نقشې جوړوي او د شونډو په چیچلو نورو ته تاوان رسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_30.mp3', '', 1761754199, 1761754199),
(43633, 'Proverbs 16:31', 'Proverbs', 16, 31, 'سپین ویښته د عزت تاج دی چې د صداقت له لارې تر‌لاسه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_31.mp3', '', 1761754199, 1761754199),
(43634, 'Proverbs 16:32', 'Proverbs', 16, 32, 'څوک چې زر نه په قهریږي له یو قوي جنګیالي نه ښه دی د خپلې غوسې سړوونکی د یو ښار له فتح کوونکي نه بهتر دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_32.mp3', '', 1761754199, 1761754199),
(43635, 'Proverbs 16:33', 'Proverbs', 16, 33, 'انسان خو پچه میدان ته اچوي خو وروستنۍ پرېکړه د څښتن په لاس کې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs16_verse_33.mp3', '', 1761754199, 1761754199),
(43636, 'Genesis 40:1', 'Genesis', 40, 1, 'څه موده وروسته د مصر د پاچا یعنې فرعون د ساقیانو او نانوایانو د مشرانو څخه د پاچا په وړاندې غلطي وشوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_1.mp3', '', 1761754199, 1761754199),
(43637, 'Genesis 40:2', 'Genesis', 40, 2, 'فرعون په دې دواړو درباریانو باندې په قهر شو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_2.mp3', '', 1761754199, 1761754199),
(43638, 'Genesis 40:3', 'Genesis', 40, 3, 'او هغوی یې په هغه زندان کې واچول چې د دربار د ساتونکو د قوماندان په کور کې ؤ یعنې په هماغه زندان کې چې یوسف په کې بندي ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_3.mp3', '', 1761754199, 1761754199),
(43639, 'Genesis 40:4', 'Genesis', 40, 4, 'هغوی زیات وخت په زندان کې تېر کړ او د ساتونکو قوماندان هغوی یوسف ته وسپارل او هغه د دوی خدمت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_4.mp3', '', 1761754199, 1761754199),
(43640, 'Genesis 40:5', 'Genesis', 40, 5, 'د ساقیانو او نانوایانو مشرانو چې په زندان کې وو، په یوه شپه دواړو خوب ولیده او هر یو خوب خپله معنی درلودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_5.mp3', '', 1761754199, 1761754199),
(43641, 'Genesis 40:6', 'Genesis', 40, 6, 'کله چې سهار یوسف هغوی ته ورغی، ویې لیدل چې هغوی خفه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_6.mp3', '', 1761754199, 1761754199),
(43642, 'Genesis 40:7', 'Genesis', 40, 7, 'نو هغه ورڅخه پوښتنه وکړه: «تاسو نن ولې دومره خفه یئ؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_7.mp3', '', 1761754199, 1761754199),
(43643, 'Genesis 40:8', 'Genesis', 40, 8, 'هغوی ځواب ورکړ: «مونږ دواړو خوبونه لیدلي دي، خو څوک نشته چې هغه تعبیر کړي.» یوسف هغوی ته وویل: «د خوبونو تعبیرول د خدای کار دی. خپل خوبونه ماته ووایئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_8.mp3', '', 1761754199, 1761754199),
(43644, 'Genesis 40:9', 'Genesis', 40, 9, 'نو د ساقیانو مشر خپل خوب یوسف ته بیان کړ. هغه ته یې وویل: «په خوب کې مې خپلې مخې ته د انګورو تاک ولیده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_9.mp3', '', 1761754199, 1761754199),
(43645, 'Genesis 40:10', 'Genesis', 40, 10, 'په تاک کې درې څانګې وې. څنګه چې غوټۍ یې وکړې، نو هغه وغوړېدلې او د انګورو وږي پاخه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_10.mp3', '', 1761754199, 1761754199),
(43646, 'Genesis 40:11', 'Genesis', 40, 11, 'د فرعون پیاله مې په لاس کې وه. نو انګور مې واخیستل او په پیاله کې مې وزبېښل او پیاله مې د فرعون په لاس کې ورکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_11.mp3', '', 1761754199, 1761754199),
(43647, 'Genesis 40:12', 'Genesis', 40, 12, 'یوسف وویل: «د هغه تعبیر دا دی: درې څانګې درې ورځې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_12.mp3', '', 1761754199, 1761754199),
(43648, 'Genesis 40:13', 'Genesis', 40, 13, 'په دې درې ورځو کې به فرعون تا ازاد کړي او وبه دې بخښي او بېرته به دې په خپل کار باندې مقرر کړي. ته به د پخوا په شان لکه څنګه چې د هغه ساقي وې، د فرعون پیاله به د هغه په لاس کې ورکوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_13.mp3', '', 1761754199, 1761754199),
(43649, 'Genesis 40:14', 'Genesis', 40, 14, 'خو کله چې داسې وشي، ما در په یاد کړه او زما سره احسان وکړه. فرعون ته زما په اړه یادونه وکړه او له دې زندان څخه مې وباسه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_14.mp3', '', 1761754199, 1761754199),
(43650, 'Genesis 40:15', 'Genesis', 40, 15, 'ځکه چې زه د عبرانیانو د وطن څخه په زور تښتول شوی یم او دلته مې هم هېڅ داسې کار نه دی کړی چې ما دې په زندان کې واچوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_15.mp3', '', 1761754199, 1761754199),
(43651, 'Genesis 40:16', 'Genesis', 40, 16, 'کله چې د نانوایانو مشر ولیدل چې ښه تعبیر دی، نو یوسف ته یې وویل: «ما هم خوب ولیده چې د ډوډیو درې ټوکرۍ مې په سر وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_16.mp3', '', 1761754199, 1761754199),
(43652, 'Genesis 40:17', 'Genesis', 40, 17, 'په پاسنۍ ټوکرۍ کې د فرعون دپاره هر ډول ډوډۍ وې او مرغانو به هغه د دې ټوکرۍ څخه خوړلې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_17.mp3', '', 1761754199, 1761754199),
(43653, 'Genesis 40:18', 'Genesis', 40, 18, 'یوسف په ځواب کې وویل: «د دې تعبیر دا دی: درې ټوکرۍ درې ورځې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_18.mp3', '', 1761754199, 1761754199),
(43654, 'Genesis 40:19', 'Genesis', 40, 19, 'په دې درې ورځو کې به فرعون ستا سر پرې کړي او تا به په ونه کې ځوړند کړي او مرغان به ستا غوښه وخوري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_19.mp3', '', 1761754199, 1761754199),
(43655, 'Genesis 40:20', 'Genesis', 40, 20, 'په درېمه ورځ د فرعون د زېږېدلو کالیزه وه. هغه خپلو درباریانو ته مېلمستیا ورکړه او د ساقیانو او نانوایانو مشران یې ازاد کړل او د خپلو درباریانو په مخکې یې حاضر کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_20.mp3', '', 1761754199, 1761754199),
(43656, 'Genesis 40:21', 'Genesis', 40, 21, 'هغه د ساقیانو مشر په خپل پخواني کار باندې مقرر کړ او پیاله یې یوځل بیا د فرعون په لاس کې ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_21.mp3', '', 1761754199, 1761754199),
(43657, 'Genesis 40:22', 'Genesis', 40, 22, 'خو د نانوایانو مشر یې په دار وخېژاوه، لکه څنګه چې یوسف هغوی ته تعبیر کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_22.mp3', '', 1761754199, 1761754199),
(43658, 'Genesis 40:23', 'Genesis', 40, 23, 'خو د ساقیانو مشر یوسف رایاد نه کړ او هغه یې بیخي هېر کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis40_verse_23.mp3', '', 1761754199, 1761754199),
(43659, 'Genesis 5:1', 'Genesis', 5, 1, 'دا د آدم د اولادې لست دی. کله چې خدای انسان پیدا کړ، هغه یې د خپل ځان په شان پیدا کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_1.mp3', '', 1761754199, 1761754199),
(43660, 'Genesis 5:2', 'Genesis', 5, 2, 'هغوی یې نر او ښځه پیدا کړل او برکت یې ورته ورکړ او هغوی یې انسانان وبلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_2.mp3', '', 1761754199, 1761754199),
(43661, 'Genesis 5:3', 'Genesis', 5, 3, 'آدم د یوسلو دېرش کالو ؤ چې د هغه زوی پیدا شو چې د هماغه په شان ؤ او په هغه باندې یې شیت نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_3.mp3', '', 1761754199, 1761754199),
(43662, 'Genesis 5:4', 'Genesis', 5, 4, 'د شیت د پیدا کېدلو څخه وروسته آدم اته سوه کاله نور هم ژوندی ؤ او نور زامن او لورګانې یې پیدا شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_4.mp3', '', 1761754199, 1761754199),
(43663, 'Genesis 5:5', 'Genesis', 5, 5, 'نو آدم د نهه سوه دېرشو کالو په عمر ؤ چې مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_5.mp3', '', 1761754199, 1761754199),
(43664, 'Genesis 5:6', 'Genesis', 5, 6, 'شیت د یوسلو پنځو کالو ؤ چې د هغه زوی انوش پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_6.mp3', '', 1761754199, 1761754199),
(43665, 'Genesis 5:7', 'Genesis', 5, 7, 'او وروسته له هغې چې دی د انوش پلار شو، شیت اته سوه اووه کاله ژوند وکړ او نور زامن او لورګانې یې پیدا شوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_7.mp3', '', 1761754199, 1761754199),
(43666, 'Genesis 5:8', 'Genesis', 5, 8, 'او په نهه سوه دولس کلنۍ کې مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_8.mp3', '', 1761754199, 1761754199),
(43667, 'Genesis 5:9', 'Genesis', 5, 9, 'انوش د نوي کالو په عمر ؤ چې زوی یې پیدا شو او د هغه نوم یې قینان کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_9.mp3', '', 1761754199, 1761754199),
