(43676, 'Genesis 5:18', 'Genesis', 5, 18, 'یارد د یوسلو دوه شپېته کالو ؤ چې د هغه زوی خنوخ پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_18.mp3', '', 1761754199, 1761754199),
(43677, 'Genesis 5:19', 'Genesis', 5, 19, 'وروسته له دې چې هغه د خنوخ پلار شو، یارد اته سوه کاله ژوند وکړ او نور زامن او لورګانې یې پیدا شوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_19.mp3', '', 1761754199, 1761754199),
