(43679, 'Genesis 5:21', 'Genesis', 5, 21, 'خنوخ د پنځه شپېته کالو ؤ چې د هغه زوی متوشالح پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_21.mp3', '', 1761754199, 1761754199),
(43680, 'Genesis 5:22', 'Genesis', 5, 22, 'وروسته له دې چې هغه د متوشالح پلار شو، خنوخ درې سوه کاله د خدای سره په دوستۍ کې تېر کړل او نور زامن او لورګانې یې پیدا شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_22.mp3', '', 1761754199, 1761754199),
(43681, 'Genesis 5:23', 'Genesis', 5, 23, 'خنوخ درې سوه پنځه شپېته کاله ژوند وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_23.mp3', '', 1761754199, 1761754199),
(43682, 'Genesis 5:24', 'Genesis', 5, 24, 'هغه د خدای سره په دوستۍ کې خپل ژوند تېر کړ او له هغې نه وروسته هغه د سترګو څخه پناه شو، ځکه چې خدای هغه پورته بوته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_24.mp3', '', 1761754199, 1761754199),
(43683, 'Genesis 5:25', 'Genesis', 5, 25, 'متوشالح د یوسلو اووه اتیا کالو ؤ چې د هغه زوی لمک پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_25.mp3', '', 1761754199, 1761754199),
(43684, 'Genesis 5:26', 'Genesis', 5, 26, 'وروسته له دې چې هغه د لمک پلار شو، متوشالح اووه سوه دوه اتیا کاله ژوند وکړ او نور زامن او لورګانې یې پیدا شوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_26.mp3', '', 1761754199, 1761754199),
(43685, 'Genesis 5:27', 'Genesis', 5, 27, 'او په نهه سوه نهه شپېته کلنۍ کې مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_27.mp3', '', 1761754199, 1761754199),
(43686, 'Genesis 5:28', 'Genesis', 5, 28, 'لمک د یوسلو دوه اتیا کالو ؤ چې د هغه زوی پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_28.mp3', '', 1761754199, 1761754199),
(43687, 'Genesis 5:29', 'Genesis', 5, 29, 'لمک وویل: «دا به زمونږ دپاره په ستونزو، په سخت کار او د لاسونو په تڼاکو کې تسلي وي چې مونږ یې په هغې ځمکې باندې کوو چې څښتن ورباندې لعنت ویلی دی.» نو په هغه باندې یې نوح نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_29.mp3', '', 1761754199, 1761754199),
(43688, 'Genesis 5:30', 'Genesis', 5, 30, 'وروسته له دې چې نوح پیدا شو، لمک پنځه سوه پنځه نوي کاله ژوند وکړ او نور زامن او لورګانې یې پیدا شوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_30.mp3', '', 1761754199, 1761754199),
(43689, 'Genesis 5:31', 'Genesis', 5, 31, 'او په اووه سوه اووه اویا کلنۍ کې مړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_31.mp3', '', 1761754199, 1761754199),
(43690, 'Genesis 5:32', 'Genesis', 5, 32, 'وروسته له دې چې نوح د پنځه سوه کالو شو، د هغه درې زامن پیدا شول چې سام، حام او یافت نومېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis5_verse_32.mp3', '', 1761754199, 1761754199),
(43691, 'Isaiah 17:1', 'Isaiah', 17, 1, 'د دمشق په اړه د څښتن پیغام: «دمشق به نور یو ښار نه وي، هغه به په کنډوالې بدل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_1.mp3', '', 1761754199, 1761754199),
(43692, 'Isaiah 17:2', 'Isaiah', 17, 2, 'د عروعیر ښارونه به د خلکو نه خالي شي. له هغو به د پسونو او غویانو څړځایونه جوړ شي او هېڅوک به یې نه شړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_2.mp3', '', 1761754199, 1761754199),
(43693, 'Isaiah 17:3', 'Isaiah', 17, 3, 'د اسراییلو جنګي کلاګانې به له منځه لاړې شي او دمشق به خپله واکمني له لاسه ورکړي. د سوریې کوم خلک چې ژوندي پاتې شي هغوی به د اسراییلیانو په شان خوار او ذلیل شي. دا زما، د مطلق قادر څښتن وینا ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_3.mp3', '', 1761754199, 1761754199),
(43694, 'Isaiah 17:4', 'Isaiah', 17, 4, 'همدارنګه څښتن وویل: «یوه داسې ورځ راتلونکې ده چې د اسراییلو لویي او دبدبه به پای ته ورسیږي او د هغوی شتمني به په نېستۍ باندې بدله شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_4.mp3', '', 1761754199, 1761754199),
(43695, 'Isaiah 17:5', 'Isaiah', 17, 5, 'اسراییل به د داسې پټي په شان وي چې لوګرو یې غلې دانې رېبلې وي، لکه د رفاییم په دره کې چې کوم پټی خالي وي او حاصل یې وړل شوی وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_5.mp3', '', 1761754199, 1761754199),
(43696, 'Isaiah 17:6', 'Isaiah', 17, 6, 'یوازې د اسراییلو د قوم یو څو کسان به ژوندي پاتې شي او هغوی به د زیتونو د داسې ونې په شان وي چې د هغې څخه ټول زیتون راټول شوي وي او تش دوه یا درې دانې یې په سر کې پاتې وي، یا د هغې مېوه لرونکې ونې په شان چې څلور یا پنځه دانې یې په څانګو کې پاتې وي. دا زما، د اسراییلو څښتن خدای وینا ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_6.mp3', '', 1761754199, 1761754199),
(43697, 'Isaiah 17:7', 'Isaiah', 17, 7, 'کله چې هغه ورځ راورسیږي، نو خلک به خپل خالق یعنې د اسراییلو سپېڅلي خدای ته رجوع وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_7.mp3', '', 1761754199, 1761754199),
(43698, 'Isaiah 17:8', 'Isaiah', 17, 8, 'هغوی به نور د قربانۍ په هغو ځایونو باندې چې په خپلو لاسونو یې جوړ کړي دي، یعنې د اشیره په بتانو او د قربانۍ په هغو ځایونو چې خوشبویي په کې سوځول کیږي، تکیه ونه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_8.mp3', '', 1761754199, 1761754199),
(43699, 'Isaiah 17:9', 'Isaiah', 17, 9, 'کله چې هغه ورځ راشي، د هغوی قوي ښارونه به شاړ او په ځنګلونو باندې بدل شي. هغه ښارونه به د هغو سیمو په شان شي چې خلکو د اسراییلو د حملې سره سم پرېښودل او هرڅه به وران او وېجاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_9.mp3', '', 1761754199, 1761754199),
(43700, 'Isaiah 17:10', 'Isaiah', 17, 10, 'ای اسراییلو، تاسو هغه خدای هېر کړی دی چې تاسو یې ژغورلي یئ او د یاده مو وتلي دي چې هغه د یو زورور ګټ په شان ستاسو ساتنه کړې ده. د هغې په ځای، تاسو ښایسته باغونه کرلي دي چې د پردیو خدایانو عبادت په کې وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_10.mp3', '', 1761754199, 1761754199),
(43701, 'Isaiah 17:11', 'Isaiah', 17, 11, 'خو حتی که په هماغه سهار کې چې تاسو هغه کرلي دي، هغه راشنه شي او وغوړیږي، بیا به هم هېڅ حاصل ورنه کړي. د دې په ځای به تاسو یوازې په غم او ناعلاجه درد اخته شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_11.mp3', '', 1761754199, 1761754199),
(43702, 'Isaiah 17:12', 'Isaiah', 17, 12, 'واورئ، بې شمېره قومونه د بحیرې په شان شور کوي، لکه د بحیرې د لویو لویو څپو د غړمبار په شان.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_12.mp3', '', 1761754199, 1761754199),
(43703, 'Isaiah 17:13', 'Isaiah', 17, 13, 'قومونه لکه د تېزو څپو په شان غړمبار کوي، خو خدای هغوی رټي او هغوی لېرې تښتي، داسې تښتي لکه د باد په وخت کې د غونډیو په سر کې بوس او یا د تند باد په وخت کې چورلېدونکي بوټي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_13.mp3', '', 1761754199, 1761754199),
(43704, 'Isaiah 17:14', 'Isaiah', 17, 14, 'قومونه په ماښام کې د زیاتې وېرې سبب ګرځي، خو په سهار کې ورکیږي. دا د هغه چا تقدیر او قسمت دی چې زمونږ وطن لوټوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah17_verse_14.mp3', '', 1761754199, 1761754199),
(43705, 'Songofsongs 3:1', 'Songofsongs', 3, 1, 'ټوله شپه کله چې زۀ په خپل کټ کښې پرته ومه، د چا سره چې زۀ مينه کوم ما د هغۀ لټون وکړونه، خو هغه رانۀ غلونه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs3_verse_1.mp3', '', 1761754199, 1761754199),
(43706, 'Songofsongs 3:2', 'Songofsongs', 3, 2, 'خو بيا ما خپل ځان ته ووئيل، زۀ به پاڅېږمه او ټول ښار به ولټومه، د هغه چا پسې به په چوکونو او سړکونو کښې وګرځېږمه چا سره چې زۀ مينه کومه. نو زۀ ورپسې ښۀ وګرځېدمه خو پېدا مې نۀ کړونه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs3_verse_2.mp3', '', 1761754199, 1761754199),
(43707, 'Songofsongs 3:3', 'Songofsongs', 3, 3, 'چوکيدارانو زۀ ودرولمه، کله چې هغوئ په ښار کښې ګرځېدل. ما د هغوئ نه تپوس وکړلو، ”ولې تاسو هغه کس ليدلے دېنه چا سره چې زۀ مينه کومه؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs3_verse_3.mp3', '', 1761754199, 1761754199),
(43708, 'Songofsongs 3:4', 'Songofsongs', 3, 4, 'نو چې د هغوئ نه لږ وړاندې لاړمه ما خپل جانان پېدا کړونه. هغه مې راټينګ کړونه او تلو ته مې پرې نۀ‎ ښودلونه او ما هغه د خپلې مور کور ته راوستونه هغې کوټې ته په کومه کښې چې زۀ د مور په ګېډه شوې ومه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs3_verse_4.mp3', '', 1761754199, 1761754199),
(43709, 'Songofsongs 3:5', 'Songofsongs', 3, 5, 'اے د يروشلم جينکو، ما سره ټينګه وعده وکړئينه، ترڅو چې مونږ پراتۀ يونه مونږ به نۀ په عذابوئينه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs3_verse_5.mp3', '', 1761754199, 1761754199),
(43710, 'Songofsongs 3:6', 'Songofsongs', 3, 6, 'چې د لوګى د ستن په شان دے هغه څوک دېنه هغه زمونږ طرف ته راروان دېنه؟ چې فضا يې په مُر او لوبانو خوشبوداره کړې ده نه، او د سوداګرو په عطرو باندې خوشبوداره کړې ده نه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/songofsongs3_verse_6.mp3', '', 1761754199, 1761754199);